import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test.describe("upload vendor documents", () => {
  test("rejects an empty file with empty_file", { tag: "@DOC-04" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const vendor = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc Empty"), category: "software", contact_email: "ops@example.com" },
    });
    expect(vendor.status(), await vendor.text()).toBe(201);
    const vendorId = (await vendor.json()).id;

    // Act
    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: { kind: "w9", file: { name: "empty.txt", mimeType: "text/plain", buffer: Buffer.alloc(0) } },
    });

    // Assert
    const body = await res.text();
    expect(res.status(), body).toBe(422);
    expect(JSON.parse(body).error.code, body).toBe("empty_file");
  });

  test("rejects a file of 10 MiB + 1 with file_too_large", { tag: "@DOC-04" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const vendor = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc Big"), category: "software", contact_email: "ops@example.com" },
    });
    expect(vendor.status(), await vendor.text()).toBe(201);
    const vendorId = (await vendor.json()).id;

    // Act
    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "big.txt", mimeType: "text/plain", buffer: Buffer.alloc(TEN_MIB + 1, "x") },
      },
    });

    // Assert
    const body = await res.text();
    expect(res.status(), body).toBe(413);
    expect(JSON.parse(body).error.code, body).toBe("file_too_large");
  });

  test("rejects a .exe file with unsupported_type", { tag: "@DOC-04" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const vendor = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc Exe"), category: "software", contact_email: "ops@example.com" },
    });
    expect(vendor.status(), await vendor.text()).toBe(201);
    const vendorId = (await vendor.json()).id;

    // Act
    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "tool.exe", mimeType: "application/octet-stream", buffer: Buffer.from("MZ") },
      },
    });

    // Assert
    const body = await res.text();
    expect(res.status(), body).toBe(415);
    expect(JSON.parse(body).error.code, body).toBe("unsupported_type");
  });

  test("rejects an unknown document kind with validation_error", { tag: "@DOC-04" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const vendor = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc Kind"), category: "software", contact_email: "ops@example.com" },
    });
    expect(vendor.status(), await vendor.text()).toBe(201);
    const vendorId = (await vendor.json()).id;

    // Act
    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: "passport",
        file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
      },
    });

    // Assert
    const body = await res.text();
    expect(res.status(), body).toBe(422);
    expect(JSON.parse(body).error.code, body).toBe("validation_error");
  });
});
